Aquecimento","what":"10 min leve","pace":"6:45–7:30/km"},{"label":"Principal","what":"3 × 10 min no limiar com 2 min de trote entre eles","pace":"5:25–5:40/km"},{"label":"Volta à calma","what":"5 min leve e 2 min caminhando","pace":null}],"easy_week":false},{"week_number":11,"run_type":"long","name":"Longão de 9,5 km","distance_km":9.5,"workout_type":"leve","purpose":"O treino mais importante para a meia: constrói resistência.","feel":"Ritmo de conversa o tempo todo.","steps":[{"label":"Longão","what":"9,5 km leve do início ao fim","pace":"6:45–7:30/km"}],"easy_week":false},{"week_number":12,"run_type":"quality","name":"Tempo run: 20 min contínuos","distance_km":6,"workout_type":"lim","purpose":"O teste do bloco: 20 minutos seguidos no limiar. Anote como se sentiu.","feel":"Confortavelmente difícil: dá para falar frases curtas. Se não der, diminua o ritmo.","steps":[{"label":"Aquecimento","what":"10 min leve","pace":"6:45–7:30/km"},{"label":"Principal","what":"20 min contínuos no limiar","pace":"5:25–5:35/km"},{"label":"Volta à calma","what":"5 min leve e 2 min caminhando","pace":null}],"easy_week":false},{"week_number":12,"run_type":"long","name":"Longão de 10 km","distance_km":10,"workout_type":"leve","purpose":"O treino mais importante para a meia: constrói resistência.","feel":"Ritmo de conversa o tempo todo.","steps":[{"label":"Longão","what":"10 km leve do início ao fim","pace":"6:45–7:30/km"},{"label":"Final","what":"Faça os últimos 2 km em ritmo de meia, perto de 6:00/km.","pace":null}],"easy_week":false}]}$seed$::jsonb;
  v_prog uuid; v_tpl uuid; v_blk uuid; v_item uuid;
  t jsonb; b jsonb; i jsonb; s jsonb; r jsonb;
begin
  insert into public.programs (slug, name, description, weeks, deload_week, deload_factor, visibility)
  values (d->'program'->>'slug', d->'program'->>'name', d->'program'->>'description',
          (d->'program'->>'weeks')::smallint, (d->'program'->>'deload_week')::smallint, (d->'program'->>'deload_factor')::numeric, 'public')
  returning id into v_prog;

  for t in select * from jsonb_array_elements(d->'templates') loop
    insert into public.workout_templates (program_id, code, name, focus, kind, color, est_minutes, position)
    values (v_prog, t->>'code', t->>'name', t->>'focus', t->>'kind', t->>'color', (t->>'est_minutes')::smallint, (t->>'position')::smallint)
    returning id into v_tpl;
    for b in select * from jsonb_array_elements(t->'blocks') loop
      insert into public.template_blocks (template_id, position, block_type, rest_seconds, optional, note)
      values (v_tpl, (b->>'position')::smallint, b->>'block_type', (b->>'rest_seconds')::smallint, (b->>'optional')::boolean, b->>'note')
      returning id into v_blk;
      for i in select * from jsonb_array_elements(b->'items') loop
        insert into public.template_items (block_id, position, exercise_id, sets, rep_min, rep_max, target_text, rir, intensity_note, side_label, deload_exempt, legacy_code)
        values (v_blk, (i->>'position')::smallint, (select id from public.exercises where slug = i->>'exercise' and owner_id is null),
                (i->>'sets')::smallint, (i->>'rep_min')::smallint, (i->>'rep_max')::smallint, i->>'target_text', i->>'rir',
                i->>'intensity_note', i->>'side_label', (i->>'deload_exempt')::boolean, i->>'legacy_code')
        returning id into v_item;
        insert into public.template_item_alternatives (item_id, exercise_id, position)
        values (v_item, (select id from public.exercises where slug = i->>'alt' and owner_id is null), 1);
      end loop;
    end loop;
  end loop;

  for s in select * from jsonb_array_elements(d->'schedule') loop
    insert into public.program_schedule (program_id, weekday, activity, template_id, run_type)
    values (v_prog, (s->>'weekday')::smallint, s->>'activity',
            (select id from public.workout_templates where program_id = v_prog and code = s->>'template'), s->>'run_type');
  end loop;

  for r in select * from jsonb_array_elements(d->'runs') loop
    insert into public.planned_runs (program_id, week_number, run_type, name, distance_km, workout_type, purpose, feel, steps, easy_week)
    values (v_prog, (r->>'week_number')::smallint, r->>'run_type', r->>'name', (r->>'distance_km')::numeric, r->>'workout_type',
            r->>'purpose', r->>'feel', r->'steps', (r->>'easy_week')::boolean);
  end loop;
end
$body$;
